// Builds the Gemini request from the transcript sent by the bot.
// Edit PROMPT to change how fragments are chosen. The model is set in the "Gemini" node URL.
const b = $json.body;
const transcript = b.transcript.map(s => `[${s.start.toFixed(1)}-${s.end.toFixed(1)}] ${s.text}`).join('\n');
const maxClips = Math.max(1, Math.floor(b.video_duration / b.target_seconds));

const PROMPT = `You are an experienced TikTok editor. Below is a timestamped transcript of a vlog / interactive video
(language: ${b.language}, duration: ${b.video_duration.toFixed(0)} s).

Pick the most engaging fragments that work as standalone TikTok videos:
- each fragment is ${b.min_seconds}-${b.max_seconds} seconds long, ideally about ${b.target_seconds} s;
- it starts with a strong hook (question, intrigue, emotion, a bold statement) and ends on a finished thought;
- start and end exactly on phrase boundaries from the transcript;
- fragments must not overlap;
- return from 1 to ${maxClips} fragments, quality over quantity, in chronological order;
- title: a short catchy caption for the post (up to 60 characters) in the video's language.

Transcript:
${transcript}`;

return [{ json: { request: {
  contents: [{ role: 'user', parts: [{ text: PROMPT }] }],
  generationConfig: {
    temperature: 0.4,
    responseMimeType: 'application/json',
    responseSchema: {
      type: 'OBJECT',
      properties: { clips: { type: 'ARRAY', items: { type: 'OBJECT',
        properties: { start: { type: 'NUMBER' }, end: { type: 'NUMBER' }, title: { type: 'STRING' } },
        required: ['start', 'end', 'title'] } } },
      required: ['clips'],
    },
  },
} } }];

// Extracts {clips: [...]} from the Gemini answer. On any problem returns an empty list with the reason,
// and the bot falls back to splitting the video into equal parts.
const j = $json;
if (j.error) {
  const e = j.error;
  const msg = e.description || e.message || JSON.stringify(e);
  return [{ json: { clips: [], error: 'Gemini: ' + String(msg).slice(0, 500) } }];
}
const cand = (j.candidates || [])[0];
if (!cand || !cand.content) {
  const why = (j.promptFeedback && j.promptFeedback.blockReason) || (cand && cand.finishReason) || 'пустой ответ';
  return [{ json: { clips: [], error: 'Gemini: ' + why } }];
}
try {
  const text = cand.content.parts.map(p => p.text || '').join('');
  const data = JSON.parse(text);
  return [{ json: { clips: Array.isArray(data.clips) ? data.clips : [] } }];
} catch (e) {
  return [{ json: { clips: [], error: 'Не удалось разобрать ответ Gemini: ' + String(e) } }];
}
